/* VapePods renderer. Data comes from data.js, which is generated by build/build.py
   from the official pages listed on each entry. This file never invents a number:
   every value it prints exists in the data, and every number is traced to a source URL. */
(function () {
  "use strict";

  var D = window.PODS_DATA;
  if (!D) {
    document.body.innerHTML = "<p style='padding:40px;font-family:system-ui'>Data file did not load.</p>";
    return;
  }

  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }
  function money(n, dec) { return n == null ? "—" : "$" + n.toFixed(dec == null ? 2 : dec); }
  function grams(size) { var m = /([\d.]+)\s*g/.exec(size || ""); return m ? parseFloat(m[1]) : null; }

  var MULT = (D.tax_estimate && D.tax_estimate.multiplier) || 1.2492;

  /* Out-the-door price.
     - "included"   -> the store's own page says tax is in the price: value as-is.
     - otherwise    -> estimate = price x multiplier (15% excise, then 8.625% sales tax),
                       flagged in the UI with the word "est." every time it appears. */
  function oot(e) {
    if (e.price == null) return null;
    return e.tax === "included" ? e.price : e.price * MULT;
  }
  function ootIsEstimate(e) { return e.price != null && e.tax !== "included"; }
  function perGramOOT(e) {
    var g = grams(e.size);
    var t = oot(e);
    return (g && t) ? t / g : null;
  }

  function taxChip(tax) {
    if (tax === "included") return '<span class="chip chip-incl" title="The store\'s own page states tax is included">TAX INCLUDED</span>';
    if (tax === "not-included") return '<span class="chip chip-excl" title="The store\'s own page states tax is added at checkout">TAX ADDED AT CHECKOUT</span>';
    return '<span class="chip chip-unsure" title="The store prints no tax note - treated as pre-tax here">TAX NOT STATED</span>';
  }
  function verifChip(e) {
    if (e.verified === "live")
      return '<span class="chip chip-live" title="Official page fetched and read on ' + esc(e.verified_date) + '">read ' + esc(e.verified_date) + '</span>';
    return '<span class="chip chip-carry" title="Read on ' + esc(e.verified_date) + ', not re-read on ' + esc(D.verified_date) + '">not re-checked today</span>';
  }
  function srcLabel(kind) {
    if (kind === "official-brand-menu") return "brand's own menu";
    if (kind === "brand-listing") return "brand-operated store listing";
    return "official store site";
  }
  function stockChip(e) {
    if (!e.stock) return "";
    var bad = /out of stock/i.test(e.stock);
    return '<span class="chip ' + (bad ? "chip-warn" : "chip-quiet") + '">' + esc(e.stock) + "</span>";
  }

  ["vd", "vd2", "vd3", "vd4"].forEach(function (id) {
    var el = $(id); if (el) el.textContent = (id === "vd3" ? D.previous_date : D.verified_date);
  });

  var dated = D.entries.filter(function (e) { return e.price != null; });
  var pods = dated.filter(function (e) { return e.type === "pod"; });

  /* ---------------- stat bar ---------------- */
  var best = pods.slice().sort(function (a, b) { return perGramOOT(a) - perGramOOT(b); })[0];
  var nearest = D.stores.slice().sort(function (a, b) { return a.distance_miles - b.distance_miles; })[0];
  var liveCount = D.entries.filter(function (e) { return e.verified === "live"; }).length;
  var stats = [
    [dated.length, "verified price lines", ""],
    [D.stores.length, "stores checked", ""],
    [best ? money(perGramOOT(best)) + "/g" : "—", "best est. out-the-door per gram", "green"],
    [liveCount, "lines re-read on " + D.verified_date, ""],
    [nearest.distance_miles.toFixed(2) + " mi", "nearest store — " + nearest.name, "amber"]
  ];
  $("statbar").innerHTML = stats.map(function (s) {
    return "<div class='stat'><div class='n " + s[2] + "'>" + esc(s[0]) + "</div><div class='l'>" + esc(s[1]) + "</div></div>";
  }).join("");

  /* ---------------- best value cards ---------------- */
  var bestList = pods.slice().sort(function (a, b) { return perGramOOT(a) - perGramOOT(b); }).slice(0, 5);
  $("best-grid").innerHTML = bestList.map(function (e, i) {
    return "<div class='best-card'>" +
      "<div class='rank'>#" + (i + 1) + " · " + esc(e.store) + " · " + e.distance_miles.toFixed(2) + " mi</div>" +
      "<div class='name'>" + esc(e.product) + "</div>" +
      "<div class='bigprice'>" + money(e.price) + "<span class='taxword'>" + (e.tax === "included" ? "incl. tax" : "before tax") + "</span></div>" +
      "<div class='meta'>" + (ootIsEstimate(e) ? "≈ " + money(oot(e)) + " out the door (est.) · " : "out the door as listed · ") +
      (perGramOOT(e) ? money(perGramOOT(e)) + "/g est." : "") + "</div>" +
      "<div class='meta'>" + taxChip(e.tax) + verifChip(e) + "</div>" +
      "<div class='meta'><a href='" + esc(e.source_url) + "' target='_blank' rel='noopener'>open the official page →</a></div>" +
      "</div>";
  }).join("");

  /* ---------------- filters ---------------- */
  var storeSel = $("f-store");
  storeSel.innerHTML = "<option value=''>All stores</option>" + D.stores.slice()
    .sort(function (a, b) { return a.distance_miles - b.distance_miles; })
    .map(function (s) {
      return "<option value='" + esc(s.name) + "'>" + esc(s.name) + " — " + s.distance_miles.toFixed(2) + " mi</option>";
    }).join("");

  function render() {
    var fs = storeSel.value, fz = $("f-size").value, fx = $("f-tax").value,
        so = $("f-sort").value, onlyNew = $("f-new").checked, onlyPods = $("f-pod").checked;

    var list = D.entries.filter(function (e) {
      if (fs && e.store !== fs) return false;
      if (fz && e.size !== fz) return false;
      if (fx && e.tax !== fx) return false;
      if (onlyNew && !e.is_new) return false;
      if (onlyPods && e.type !== "pod") return false;
      return true;
    });

    list.sort(function (a, b) {
      if (so === "oot-asc") return (oot(a) || 1e9) - (oot(b) || 1e9);
      if (so === "price-asc") return (a.price || 1e9) - (b.price || 1e9);
      if (so === "dist-asc") return a.distance_miles - b.distance_miles || (a.price || 1e9) - (b.price || 1e9);
      if (so === "pergram-asc") return (perGramOOT(a) || 1e9) - (perGramOOT(b) || 1e9);
      if (so === "store") return a.store.localeCompare(b.store) || (a.price || 1e9) - (b.price || 1e9);
      return 0;
    });

    $("entry-count").textContent = "(" + list.length + " shown of " + D.entries.length + ")";

    $("entry-list").innerHTML = list.map(function (e) {
      var was = e.price_was ? "<s>" + money(e.price_was) + "</s> " : "";
      var ootTxt = e.price == null ? "" :
        (ootIsEstimate(e)
          ? "<span class='oot est'>≈ " + money(oot(e)) + " out the door <em>(est.)</em></span>"
          : "<span class='oot final'>" + money(oot(e)) + " out the door</span>");
      return "<article class='entry" + (e.is_new ? " is-new" : "") + "'>" +
        "<div class='row1'>" +
          "<h3>" + esc(e.product) + "</h3>" +
          "<div class='chips'>" + (e.is_new ? "<span class='chip chip-new'>NEW THIS PASS</span>" : "") +
            taxChip(e.tax) + verifChip(e) + stockChip(e) + "</div>" +
        "</div>" +
        "<div class='row2'>" +
          "<div class='priceblock'>" +
            "<div class='price'>" + (e.price == null ? "see page" : money(e.price)) + " " + was + "</div>" +
            "<div class='base'>" + (e.price == null ? "" : "base price as listed" + (e.price_was ? " (was)" : "")) + "</div>" +
            ootTxt +
          "</div>" +
          "<dl class='facts'>" +
            "<div><dt>Where</dt><dd>" + esc(e.store) + " · " + e.distance_miles.toFixed(2) + " mi from 94122</dd></div>" +
            "<div><dt>Format</dt><dd>" + esc(e.size) + " · " + esc(e.type === "pod" ? "pod (fits STIIIZY pen)" : (e.type === "aio" ? "all-in-one pen" : "battery / hardware")) +
              (e.thc ? " · THC " + esc(e.thc) : "") + "</dd></div>" +
            "<div><dt>Deal</dt><dd>" + (e.deal ? esc(e.deal) : "none listed on the page") + "</dd></div>" +
            "<div><dt>Source</dt><dd><a href='" + esc(e.source_url) + "' target='_blank' rel='noopener'>" + esc(e.source_url) + "</a> <span class='kind'>(" + esc(srcLabel(e.source_kind)) + ")</span></dd></div>" +
            (e.notes ? "<div><dt>Note</dt><dd class='note'>" + esc(e.notes) + "</dd></div>" : "") +
          "</dl>" +
        "</div>" +
        "<div class='compat'>" + esc(e.compat) + "</div>" +
      "</article>";
    }).join("");
  }

  ["f-store", "f-size", "f-tax", "f-sort"].forEach(function (id) { $(id).addEventListener("change", render); });
  ["f-new", "f-pod"].forEach(function (id) { $(id).addEventListener("change", render); });
  render();

  /* ---------------- stores ---------------- */
  $("store-grid").innerHTML = D.stores.map(function (s) {
    var deals = (s.deals || []).map(function (d) {
      var warn = /FLAG|OUT OF STOCK|no Stiiizy|ON SALE flag/i.test(d) ? " class='warn'" : "";
      return "<li" + warn + ">" + esc(d) + "</li>";
    }).join("");
    return "<div class='store-card'>" +
      "<h3>" + esc(s.name) + " <span class='dist'>" + s.distance_miles.toFixed(2) + " mi</span></h3>" +
      "<p class='addr'>" + esc(s.address) + (s.phone && s.phone !== "-" ? " · " + esc(s.phone) : "") + "</p>" +
      "<p class='hrs'>" + esc(s.hours) + "</p>" +
      "<p class='taxline'>" + taxChip(s.tax) + " " + esc(s.tax_note) + "</p>" +
      (deals ? "<div class='deals'><h4>Deals seen on the official page</h4><ul>" + deals + "</ul></div>" : "") +
      "<div class='links'>" +
        "<a href='" + esc(s.url) + "' target='_blank' rel='noopener'>Store page</a>" +
        "<a href='" + esc(s.menu_url) + "' target='_blank' rel='noopener'>Live menu</a>" +
        (s.specials_url && s.specials_url !== s.menu_url ? "<a href='" + esc(s.specials_url) + "' target='_blank' rel='noopener'>Specials</a>" : "") +
      "</div>" +
      "<p class='srcstat'>" + esc(s.source_status) + "</p>" +
      "</div>";
  }).join("");

  $("loc-list").innerHTML = D.other_locations.map(function (l) {
    return "<div class='loc'><div class='lname'>" + esc(l[0]) + "</div>" +
      "<div>" + esc(l[1]) + " · " + esc(l[2]) + "</div>" +
      "<div>" + esc(l[3]) + "</div>" +
      "<div><a href='" + esc(l[4]) + "' target='_blank' rel='noopener'>Official store page →</a></div>" +
      "<div class='note'>" + esc(l[5]) + "</div></div>";
  }).join("");

  /* ---------------- tax section: what each store prints ---------------- */
  $("tax-store-list").innerHTML = D.stores.map(function (s) {
    return "<li><strong>" + esc(s.name) + ":</strong> " + esc(s.tax_note) + "</li>";
  }).join("");

  /* ---------------- flags ---------------- */
  $("flag-list").innerHTML = D.flags.map(function (f) {
    var kind = f[0] === "FLAG" ? "f-flag" : "f-info";
    var tag = f[0] === "FLAG" ? "REVIEW" : "NOTE";
    return "<div class='flag " + kind + "'><span class='tag'>" + tag + "</span><div>" +
      "<p>" + esc(f[1]) + "</p>" +
      (f[2] ? "<a href='" + esc(f[2]) + "' target='_blank' rel='noopener'>" + esc(f[2]) + "</a>" : "") +
      "</div></div>";
  }).join("");
})();
